package com.galleryvote.submission;
import com.galleryvote.config.JwtSupport; import com.galleryvote.contest.*; import com.galleryvote.user.*; import jakarta.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api") public class SubmissionController {private final SubmissionRepository submissions;private final ContestRepository contests;private final UserRepository users;private final StorageService storage;public SubmissionController(SubmissionRepository s,ContestRepository c,UserRepository u,StorageService x){submissions=s;contests=c;users=u;storage=x;}
 public record View(Long id,Long contestId,String title,String author,String objectKey,String contentType){static View of(Submission s){return new View(s.getId(),s.getContest().getId(),s.getTitle(),s.getAuthor().getUsername(),s.getObjectKey(),s.getContentType());}}
 @GetMapping("/contests/{id}/submissions")Page<View>list(@PathVariable Long id,@PageableDefault(size=24,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return submissions.findByContestId(id,p).map(View::of);}
 @PostMapping(value="/contests/{id}/submissions",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)@ResponseStatus(HttpStatus.CREATED)View create(@PathVariable Long id,@RequestParam @NotBlank @Size(max=160)String title,@RequestPart MultipartFile image,Authentication a){Contest c=contests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Contest not found"));User u=users.findById(JwtSupport.userId(a)).orElseThrow();String key=storage.store(image);return View.of(submissions.save(new Submission(c,u,title,key,image.getContentType())));}}
